mapper.insert:
/* recipe.selectRecipeSeq */
INSERT INTO lab_recipe(
	RECIPE_IDX
	, DOC_NO
	, VERSION_NO
	, PRODUCT_CODE
	, PRODUCT_NAME
	, PLANT
	, PRODUCT_COUNT
	, PRODUCT_UNIT
	, IS_DELETE
	, IS_LAST
	, REG_USER
	, DOC_OWNER
	, STATUS
)VALUES(
	#{idx}
	, (SELECT ifnull(MAX(lr.DOC_NO),0)+1 FROM lab_recipe lr WHERE 1 = 1)
	
		
		, (SELECT ifnull(MAX(lr.VERSION_NO),0)+1 FROM lab_recipe lr WHERE 1 = 1 AND PRODUCT_CODE = #{productCode})	
		
		
		, 1
		
	
	, #{productCode}
	, #{productName}
	, #{plant}
	, #{productCount}
	, #{unit}
	, 'N'
	, 'Y'
	, #{userId}
	, #{userId}
	, #{status}
)

mapper.select:
/* recipe.selectMyDataCount */
SELECT
	COUNT(RECIPE_IDX) AS cnt
FROM 
	lab_recipe
WHERE 1 = 1
	AND RECIPE_IDX = #{idx}
	AND DOC_OWNER = #{userId}
	AND IS_DELETE = 'N'
	
	AND STATUS IN ('COMP', 'BOM_ERROR')

mapper.update:
/* recipe.updateRecipe */
UPDATE 
	lab_recipe
SET
	PLANT = #{plant}
	, PRODUCT_COUNT = #{productCount}
	, PRODUCT_UNIT = #{unit}			
	, STATUS = #{status}
	
WHERE 1 = 1
	AND RECIPE_IDX = #{idx}
	AND DOC_NO = #{docNo}

mapper.delete:
/* recipe.deleteRecipeMaterial */
DELETE
FROM lab_recipe_material
WHERE 1 = 1
	AND RECIPE_IDX = #{idx}

/* recipe.deleteRecipePurchase */
DELETE
FROM lab_recipe_purchase
WHERE 1 = 1
	AND RECIPE_IDX = #{idx}

mapper.insert:
/* recipe.insertVersionUpRecipe */
INSERT INTO lab_recipe(
	RECIPE_IDX
	, DOC_NO
	, VERSION_NO
	, PRODUCT_CODE
	, PRODUCT_NAME
	, PLANT
	, PRODUCT_COUNT
	, PRODUCT_UNIT
	, IS_DELETE
	, IS_LAST
	, REG_USER
	, DOC_OWNER
	, STATUS
)VALUES(
	#{idx}
	, #{docNo}
	, #{versionNo}+1
	, #{productCode}
	, #{productName}
	, #{plant}
	, #{productCount}
	, #{unit}
	, 'N'
	, 'Y'
	, #{userId}
	, #{userId}
	, #{status}
)

mapper.update:
/* recipe.updateRecipeIsLast */
UPDATE 
	lab_recipe
SET
	IS_LAST = 'N'
WHERE 1 = 1
	AND RECIPE_IDX = #{currentIdx}
	AND DOC_NO = #{docNo}

/* recipe.updateStatus */
UPDATE 
	lab_recipe
SET
	STATUS = #{status}
	, RESULT_MESSAGE = #{message} 
WHERE 1 = 1
	AND RECIPE_IDX = #{idx}
